'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { ArrowTrendingUpIcon, ChartBarIcon } from '@heroicons/react/24/outline';
import { formatCurrency, formatNumber } from '@/lib/utils';

// Mock data for development
const mockAnalytics = {
  totalRevenue: 45678.90,
  totalSales: 1247,
  averageOrderValue: 36.63,
  topProducts: [
    { name: 'Wireless Mouse Pro', sales: 234, revenue: 7017.66 },
    { name: 'Mechanical Keyboard', sales: 156, revenue: 14037.44 },
    { name: 'USB-C Cable', sales: 189, revenue: 2455.11 },
  ],
  salesByMonth: [
    { month: 'Jan', sales: 234, revenue: 8456.78 },
    { month: 'Feb', sales: 189, revenue: 6920.31 },
    { month: 'Mar', sales: 267, revenue: 9785.40 },
  ],
  branchComparison: [
    { name: 'Main Branch', sales: 567, revenue: 20345.89 },
    { name: 'North Branch', sales: 234, revenue: 8456.78 },
    { name: 'East Branch', sales: 446, revenue: 16876.23 },
  ],
};

export default function AnalyticsPage() {
  const [selectedPeriod, setSelectedPeriod] = useState('30d');

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Page Header */}
          <div>
            <h1 className="text-2xl font-bold text-primary">Analytics</h1>
            <p className="mt-1 text-sm text-text-secondary">
              Track sales performance and business insights
            </p>
          </div>

          {/* Period Selector */}
          <div className="card p-4">
            <div className="flex items-center space-x-4">
              <label className="text-sm font-medium text-primary">Period:</label>
              <select
                value={selectedPeriod}
                onChange={(e) => setSelectedPeriod(e.target.value)}
                className="input-field w-48"
              >
                <option value="7d">Last 7 days</option>
                <option value="30d">Last 30 days</option>
                <option value="90d">Last 90 days</option>
                <option value="1y">Last year</option>
              </select>
            </div>
          </div>

          {/* Key Metrics */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-success/10 rounded-lg">
                  <ChartBarIcon className="h-6 w-6 text-success" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">Total Revenue</p>
                  <p className="text-2xl font-bold text-primary">{formatCurrency(mockAnalytics.totalRevenue)}</p>
                </div>
              </div>
            </div>
            
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-primary/10 rounded-lg">
                  <ArrowTrendingUpIcon className="h-6 w-6 text-primary" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">Total Sales</p>
                  <p className="text-2xl font-bold text-primary">{formatNumber(mockAnalytics.totalSales)}</p>
                </div>
              </div>
            </div>
            
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-info/10 rounded-lg">
                  <ChartBarIcon className="h-6 w-6 text-info" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">Avg Order Value</p>
                  <p className="text-2xl font-bold text-primary">{formatCurrency(mockAnalytics.averageOrderValue)}</p>
                </div>
              </div>
            </div>
            
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-warning/10 rounded-lg">
                  <ChartBarIcon className="h-6 w-6 text-warning" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">Conversion Rate</p>
                  <p className="text-2xl font-bold text-primary">3.2%</p>
                </div>
              </div>
            </div>
          </div>

          {/* Charts Section */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Sales Trend Chart */}
            <div className="card p-6">
              <h3 className="text-lg font-medium text-primary mb-4">Sales Trend</h3>
              <div className="h-64 flex items-center justify-center bg-surface rounded-lg">
                <div className="text-center">
                  <ChartBarIcon className="h-12 w-12 text-text-secondary mx-auto mb-2" />
                  <p className="text-sm text-text-secondary">Chart visualization would go here</p>
                  <p className="text-xs text-text-secondary">Integration with Chart.js or Recharts</p>
                </div>
              </div>
            </div>

            {/* Top Products */}
            <div className="card p-6">
              <h3 className="text-lg font-medium text-primary mb-4">Top Products</h3>
              <div className="space-y-3">
                {mockAnalytics.topProducts.map((product, index) => (
                  <div key={index} className="flex items-center justify-between p-3 bg-surface rounded-lg">
                    <div className="flex items-center space-x-3">
                      <span className="text-lg font-medium text-primary">{index + 1}</span>
                      <div>
                        <div className="text-sm font-medium text-primary">{product.name}</div>
                        <div className="text-xs text-text-secondary">{product.sales} sold</div>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-sm font-medium text-primary">{formatCurrency(product.revenue)}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Branch Performance */}
          <div className="card p-6">
            <h3 className="text-lg font-medium text-primary mb-4">Branch Performance</h3>
            <div className="space-y-4">
              {mockAnalytics.branchComparison.map((branch) => (
                <div key={branch.name} className="flex items-center justify-between p-4 bg-surface rounded-lg">
                  <div>
                    <div className="text-sm font-medium text-primary">{branch.name}</div>
                    <div className="text-xs text-text-secondary">{branch.sales} sales</div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm font-medium text-primary">{formatCurrency(branch.revenue)}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
